// Bind a comma-separated string to a list of ints
public class CommaSeparatedArrayModelBinder : IModelBinder
{
    public Task BindModelAsync(ModelBindingContext context)
    {
        var value = context.ValueProvider.GetValue(context.ModelName).ToString();
        if (string.IsNullOrEmpty(value))
        {
            return Task.CompletedTask;
        }
        var elements = value.Split(',', StringSplitOptions.RemoveEmptyEntries)
            .Select(int.Parse)
            .ToArray();
        context.Result = ModelBindingResult.Success(elements);
        return Task.CompletedTask;
    }
}

