// Action filter - runs before and after action execution
public class LogActionFilter : IActionFilter
{
    private readonly ILogger<LogActionFilter> _logger;

    public LogActionFilter(ILogger<LogActionFilter> logger)
    {
        _logger = logger;
    }

    public void OnActionExecuting(ActionExecutingContext context)
    {
        _logger.LogInformation("Executing {Action}",
            context.ActionDescriptor.DisplayName);
    }

    public void OnActionExecuted(ActionExecutedContext context)
    {
        if (context.Exception != null)
        {
            _logger.LogError(context.Exception, "Action threw exception");
        }
    }
}

// Exception filter - handles exceptions
public class ApiExceptionFilter : IExceptionFilter
{
    private readonly IHostEnvironment _env;

    public ApiExceptionFilter(IHostEnvironment env)
    {
        _env = env;
    }

    public void OnException(ExceptionContext context)
    {
        var result = new ObjectResult(new
        {
            error = "An unexpected error occurred.",
            detail = _env.IsDevelopment() ? context.Exception.Message : null
        })
        {
            StatusCode = 500
        };

        context.Result = result;
        context.ExceptionHandled = true;
    }
}

