// Single file upload
[HttpPost("upload")]
public async Task<IActionResult> Upload([FromForm] IFormFile file)
{
    if (file == null || file.Length == 0)
        return BadRequest("No file uploaded.");

    if (file.Length > 10 * 1024 * 1024)
        return BadRequest("File too large. Max 10MB.");

    var allowedExtensions = new[] { ".jpg", ".png", ".pdf" };
    var extension = Path.GetExtension(file.FileName).ToLowerInvariant();
    if (!allowedExtensions.Contains(extension))
        return BadRequest("Invalid file type.");

    var uploadsFolder = Path.Combine(_env.WebRootPath, "uploads");
    Directory.CreateDirectory(uploadsFolder);
    var filePath = Path.Combine(uploadsFolder, Guid.NewGuid() + extension);

    await using var stream = new FileStream(filePath, FileMode.Create);
    await file.CopyToAsync(stream);

    return Ok(new { filePath, fileName = file.FileName, size = file.Length });
}

// Multiple files
[HttpPost("upload-many")]
public async Task<IActionResult> UploadMany([FromForm] List<IFormFile> files)
{
    var results = new List<object>();

    foreach (var file in files.Take(10))
    {
        if (file.Length > 0)
        {
            var filePath = Path.Combine(_env.WebRootPath, file.FileName);
            await using var stream = new FileStream(filePath, FileMode.Create);
            await file.CopyToAsync(stream);
            results.Add(new { file.FileName, file.Length });
        }
    }

    return Ok(results);
}

// Large file streaming
[HttpPost("upload-stream")]
public async Task<IActionResult> StreamUpload()
{
    var fileSize = Request.ContentLength ?? 0;
    if (fileSize > 500 * 1024 * 1024)
        return BadRequest("File exceeds 500MB limit.");

    var filePath = Path.Combine(_env.WebRootPath, "large-upload.bin");
    await using var stream = new FileStream(filePath, FileMode.Create, FileAccess.Write);
    await Request.Body.CopyToAsync(stream);

    return Ok(new { fileSize, savedTo = filePath });
}

