// gRPC service implementation
public class ProductService : Product.ProductServiceBase
{
    private readonly IProductService _service;

    public ProductService(IProductService service)
    {
        _service = service;
    }

    public override async Task<ProductResponse> GetProduct(ProductRequest request, ServerCallContext context)
    {
        var product = await _service.GetByIdAsync(request.Id);
        if (product == null)
            throw new RpcException(new Status(StatusCode.NotFound, "Product not found"));

        return new ProductResponse
        {
            Id = product.Id,
            Name = product.Name,
            Price = product.Price
        };
    }

    public override async Task ListProducts(ListRequest request, IServerStreamWriter<ProductResponse> responseStream, ServerCallContext context)
    {
        var products = await _service.GetAllAsync();
        foreach (var product in products)
        {
            await responseStream.WriteAsync(new ProductResponse
            {
                Id = product.Id,
                Name = product.Name,
                Price = product.Price
            });
        }
    }
}

